        Assert.Throws<ArgumentOutOfRangeException>(() => machine.Execute(A(0, 0), null!));
    }

    // ---- Comparaison avec le modèle de référence, sur une large part du domaine -------------------

    public static TheoryData<Denomination?> Jams => new() { null, Denomination.Fifty, Denomination.Twenty, Denomination.Ten };

    [Theory]
    [MemberData(nameof(Jams))]
    public void MatchesOracle_AcrossDomain(Denomination? jammed)
    {
        int[] balances = [0, 5, 10, 45, 50, 55, 100, 105, 110, 115, 150, 200, 205, 250];
        int[] withdrawnValues = [0, 10, 50, 100, 150, 190, 200];
        var amounts = new[] { -10, 0, 5 }.Concat(Enumerable.Range(1, 22).Select(i => i * 10));
        var operations = amounts.Select(a => (Operation)new Operation.Withdraw(a))
            .Concat(from f in new[] { 0, 1 } from t in new[] { 0, 1 } from c in new[] { 0, 1 }
                    select (Operation)new Operation.Deposit(N(f, t, c)))
            .ToArray();

        var failures = new List<string>();
        for (var sf = 0; sf <= 5; sf++)
        for (var st = 0; st <= 5; st++)
        for (var sc = 0; sc <= 5; sc++)
        foreach (var balance in balances)
        foreach (var withdrawn in withdrawnValues)
        foreach (var operation in operations)
        {
            var stock = N(sf, st, sc);
            var account = A(balance, withdrawn);
            var dispenser = new MoneyDispenser(stock, jammed);
            var actual = new CashMachine(dispenser).Execute(account, operation);
            var expected = Oracle.Expected(account, stock, jammed, operation);

            var expectedStock = actual.Status != AtmStatus.Ok ? stock
                : operation is Operation.Deposit(var deposited) ? stock + deposited
                : stock - expected.Notes;

            if (actual != expected || dispenser.Stock != expectedStock)
            {
                failures.Add($"{account} {stock} {jammed} {operation}: attendu {expected}, obtenu {actual}");
                if (failures.Count > 10) break;
            }
        }

        Assert.Empty(failures);
    }
}
namespace Atm.Tests;

/// <summary>Un module qui enregistre les appels et peut tomber en panne à la demande.</summary>
internal sealed class FaultyDispenser(NoteCounts stock, Denomination? jammed = null) : IMoneyDispenser
{
    private readonly MoneyDispenser real = new(stock, jammed);

    /// <summary>Le passage (indice à partir de 0) qui échoue, ou -1.</summary>
    public int FailDispenseAt { get; init; } = -1;

    public bool FailLoad { get; init; }

    public List<NoteCounts> Dispensed { get; } = [];

    public List<NoteCounts> Loaded { get; } = [];

    public NoteCounts Stock => real.Stock;

    public Denomination? Jammed => real.Jammed;

    public bool Dispense(NoteCounts notes)
    {
        if (Dispensed.Count == FailDispenseAt)
        {
            Dispensed.Add(default);
            return false;
        }

        Dispensed.Add(notes);
        return real.Dispense(notes);
    }

    public bool Load(NoteCounts notes)
    {
        Loaded.Add(notes);
        return !FailLoad && real.Load(notes);
    }
}

/// <summary>Un modèle de référence, écrit indépendamment, directement depuis la spécification.</summary>
internal static class Oracle
{
    public static AtmResult Expected(AccountState account, NoteCounts stock, Denomination? jammed, Operation operation)
    {
        AtmResult Refuse(AtmStatus status) => new(status, NoteCounts.None, 0, account);

        switch (operation)
        {
            case Operation.Withdraw(var amount):
            {
                if (amount <= 0 || amount % 10 != 0) return Refuse(AtmStatus.InvalidAmount);
                if (account.WithdrawnToday + amount > 200) return Refuse(AtmStatus.DailyLimitExceeded);
                var fee = amount > 100 ? 5 : 0;
                if (amount + fee > account.Balance) return Refuse(AtmStatus.InsufficientFunds);

                int Avail(Denomination d) => jammed == d ? 0 : stock.Of(d);
                NoteCounts? best = null;
                for (var f = 0; f <= Avail(Denomination.Fifty); f++)
                for (var t = 0; t <= Avail(Denomination.Twenty); t++)
                for (var c = 0; c <= Avail(Denomination.Ten); c++)
                {
                    var n = new NoteCounts(f, t, c);
                    if (n.Value == amount && (best is null || n.Total < best.Value.Total)) best = n;
                }

                if (best is not { } notes) return Refuse(AtmStatus.CannotDispense);
                return new AtmResult(AtmStatus.Ok, notes, fee,
                    new AccountState(account.Balance - amount - fee, account.WithdrawnToday + amount));
            }

            case Operation.Deposit(var notes):
            {
                if (notes.Total == 0) return Refuse(AtmStatus.InvalidAmount);
                if (jammed is { } j && notes.Of(j) > 0) return Refuse(AtmStatus.CassetteJammed);
                var after = stock + notes;
                if (after.Fifties > 5 || after.Twenties > 5 || after.Tens > 5) return Refuse(AtmStatus.CassetteFull);
                return new AtmResult(AtmStatus.Ok, NoteCounts.None, 0,
                    account with { Balance = account.Balance + notes.Value });
            }

            default:
                throw new ArgumentOutOfRangeException(nameof(operation));
        }
    }
}
namespace Atm;

/// <summary>Le vrai module de billets, déterministe.</summary>
public sealed class MoneyDispenser(NoteCounts stock, Denomination? jammed = null) : IMoneyDispenser
{
    public const int MaxNotesPerPass = 4;
    public const int CassetteCapacity = 5;

    public NoteCounts Stock { get; private set; } = stock;

    public Denomination? Jammed { get; } = jammed;

    public bool Dispense(NoteCounts notes)
    {
        var enough = notes.Fifties <= Stock.Fifties && notes.Twenties <= Stock.Twenties && notes.Tens <= Stock.Tens;
        if (!IsValid(notes) || notes.Total > MaxNotesPerPass || !enough)
        {
            return false;
        }

        Stock -= notes;

        return true;
    }

    public bool Load(NoteCounts notes)
    {
        var after = Stock + notes;
        var fits = after.Fifties <= CassetteCapacity && after.Twenties <= CassetteCapacity && after.Tens <= CassetteCapacity;
        if (!IsValid(notes) || !fits)
        {
            return false;
        }

        Stock = after;

        return true;
    }

    private bool IsValid(NoteCounts notes) =>
        notes is { Fifties: >= 0, Twenties: >= 0, Tens: >= 0, Total: > 0 }
        && (Jammed is not { } cassette || notes.Of(cassette) == 0);
}

