import itertools, operator as op
GB=[0,5,10,45,50,55,100,105,110,115,150,200,205,250]
GW=[0,10,50,100,150,190,200]
DB=range(0,251,5); DW=range(0,201,10)
AM=[-10,0,5]+list(range(10,221,10))
def ref(B,w,A, fee_f=lambda A,B,w:5 if A>100 else 0, daily=lambda A,B,w,fee:w+A>200, funds=lambda A,B,w,fee:A+fee>B, nb=lambda A,B,w,fee:B-A-fee, nw=lambda A,B,w,fee:w+A):
    if A<=0 or A%10: return 'I'
    if daily(A,B,w,None): return 'D'
    fee=fee_f(A,B,w)
    if funds(A,B,w,fee): return 'F'
    return ('OK',fee,nb(A,B,w,fee),nw(A,B,w,fee))
names={'A':lambda A,B,w,f:A,'B':lambda A,B,w,f:B,'w':lambda A,B,w,f:w,'f':lambda A,B,w,f:f or 0}
consts=[0,4,5,10,50,100,200]
ops={'>':op.gt,'>=':op.ge,'<':op.lt,'<=':op.le}
# generic: X + Y  cmp  Z + k  forms
terms=list(names)
exprs=[]
for a,b in itertools.combinations_with_replacement(terms+['0'],2):
  for c in terms+['0']:
    for k in consts:
      for o in ops:
        for kd in ['/10*10','/50*50','']:
          exprs.append((a,b,c,k,o,kd))
def mk(e):
  a,b,c,k,o,kd=e
  g=lambda n:(lambda A,B,w,f:0) if n=='0' else names[n]
  ga,gb,gc=g(a),g(b),g(c); oo=ops[o]
  def rnd(x):
    if kd=='/10*10': return int(x/10)*10
    if kd=='/50*50': return int(x/50)*50
    return x
  return lambda A,B,w,f: oo(ga(A,B,w,f)+gb(A,B,w,f), rnd(gc(A,B,w,f)+k))
def diff(kw,Bs,Ws):
  for B in Bs:
    for w in Ws:
      for A in AM:
        if ref(B,w,A)!=ref(B,w,A,**kw): return (B,w,A)
  return None
res=[]
for slot in ['daily','funds']:
  for e in exprs:
    f=mk(e)
    if diff({slot:f},GB,GW) is None:
      d=diff({slot:f},DB,DW)
      if d: res.append((slot,e,d))
for r in res: print(r)
print(len(res))
EOF
